#!/usr/bin/env python3
import sys
import re

sys.setrecursionlimit(500000)
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)


class MCParseError(Exception):
    pass


class MCTypeError(Exception):
    pass


class MCRuntimeError(Exception):
    pass


# ============================================================================
# 1. Lexer
# ============================================================================

TOKEN_REGEX = re.compile(
    r"(?P<WS>[ \t\n\r\x0b\x0c]+)"
    r"|(?P<COMMENT>--[^\n]*)"
    r"|(?P<ARROW>->)"
    r"|(?P<FLOORDIV>//)"
    r"|(?P<EQEQ>==)"
    r"|(?P<LPAREN>\()"
    r"|(?P<RPAREN>\))"
    r"|(?P<SLASH>/)"
    r"|(?P<PLUS>\+)"
    r"|(?P<MINUS>-)"
    r"|(?P<STAR>\*)"
    r"|(?P<PERCENT>%)"
    r"|(?P<LT><)"
    r"|(?P<EQ>=)"
    r"|(?P<COLON>:)"
    r"|(?P<INT>[0-9]+)"
    r"|(?P<LOWER>[a-z_][A-Za-z0-9_]*)"
    r"|(?P<UPPER>[A-Z][A-Za-z0-9_]*)"
    r"|(?P<MISMATCH>[\s\S])"
)

KEYWORDS = {
    "let": "LET",
    "rec": "REC",
    "in": "IN",
    "if": "IF",
    "then": "THEN",
    "else": "ELSE",
}

RESERVED_WORDS = {"match", "with", "type", "forall"}

UPPER_TOKENS = {
    "True": "TRUE",
    "False": "FALSE",
    "Int": "INT_TYPE",
    "Bool": "BOOL_TYPE",
}


def tokenize(src: str):
    tokens = []
    append = tokens.append
    for m in TOKEN_REGEX.finditer(src):
        kind = m.lastgroup
        if kind == "WS" or kind == "COMMENT":
            continue
        val = m.group()
        if kind == "LOWER":
            if val == "_" or val in RESERVED_WORDS:
                raise MCParseError(f"invalid identifier {val!r}")
            kw = KEYWORDS.get(val)
            if kw is not None:
                append((kw, val))
            else:
                append(("IDENT", val))
        elif kind == "UPPER":
            ut = UPPER_TOKENS.get(val)
            if ut is None:
                raise MCParseError(f"invalid uppercase name {val!r}")
            append((ut, val))
        elif kind == "INT":
            append(("INT", int(val)))
        elif kind == "MISMATCH":
            raise MCParseError(f"unexpected character {val!r}")
        else:
            append((kind, val))
    append(("EOF", None))
    return tokens


# ============================================================================
# 2. AST & Types
# ============================================================================

class TBase:
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name

    def __repr__(self):
        return self.name


T_INT = TBase("Int")
T_BOOL = TBase("Bool")


class TFun:
    __slots__ = ("arg", "ret")

    def __init__(self, arg, ret):
        self.arg = arg
        self.ret = ret

    def __repr__(self):
        return f"({self.arg} -> {self.ret})"


class TVar:
    __slots__ = ("instance",)

    def __init__(self):
        self.instance = None


class IntLit:
    __slots__ = ("val",)

    def __init__(self, val: int):
        self.val = val


class BoolLit:
    __slots__ = ("val",)

    def __init__(self, val: bool):
        self.val = val


class Var:
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name


class Lam:
    __slots__ = ("param", "body")

    def __init__(self, param: str, body):
        self.param = param
        self.body = body


class App:
    __slots__ = ("fn", "arg")

    def __init__(self, fn, arg):
        self.fn = fn
        self.arg = arg


class BinOp:
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left, right):
        self.op = op
        self.left = left
        self.right = right


class If:
    __slots__ = ("cond", "then_e", "else_e")

    def __init__(self, cond, then_e, else_e):
        self.cond = cond
        self.then_e = then_e
        self.else_e = else_e


class Anno:
    __slots__ = ("expr", "ty")

    def __init__(self, expr, ty):
        self.expr = expr
        self.ty = ty


class Let:
    __slots__ = ("name", "ty", "val_e", "body_e")

    def __init__(self, name: str, ty, val_e, body_e):
        self.name = name
        self.ty = ty
        self.val_e = val_e
        self.body_e = body_e


class LetRec:
    __slots__ = ("name", "ty", "lam_e", "body_e")

    def __init__(self, name: str, ty, lam_e: Lam, body_e):
        self.name = name
        self.ty = ty
        self.lam_e = lam_e
        self.body_e = body_e


# ============================================================================
# 3. Parser
# ============================================================================

ATOM_START = {"IDENT", "INT", "TRUE", "FALSE", "LPAREN"}


class Parser:
    __slots__ = ("tokens", "pos")

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def expect(self, kind: str):
        tok = self.tokens[self.pos]
        if tok[0] != kind:
            raise MCParseError(f"expected {kind}, got {tok[0]}")
        self.pos += 1
        return tok[1]

    def parse_program(self):
        e = self.parse_expr()
        if self.tokens[self.pos][0] != "EOF":
            raise MCParseError("expected EOF")
        return e

    def parse_expr(self):
        kind = self.tokens[self.pos][0]
        if kind == "SLASH":
            self.pos += 1
            param = self.expect("IDENT")
            self.expect("ARROW")
            body = self.parse_expr()
            return Lam(param, body)
        if kind == "LET":
            self.pos += 1
            if self.tokens[self.pos][0] == "REC":
                self.pos += 1
                name = self.expect("IDENT")
                self.expect("COLON")
                ty = self.parse_type()
                self.expect("EQ")
                e1 = self.parse_expr()
                if not isinstance(e1, Lam):
                    raise MCParseError("let rec RHS must be a lambda")
                self.expect("IN")
                e2 = self.parse_expr()
                return LetRec(name, ty, e1, e2)
            else:
                name = self.expect("IDENT")
                ty = None
                if self.tokens[self.pos][0] == "COLON":
                    self.pos += 1
                    ty = self.parse_type()
                self.expect("EQ")
                e1 = self.parse_expr()
                self.expect("IN")
                e2 = self.parse_expr()
                return Let(name, ty, e1, e2)
        if kind == "IF":
            self.pos += 1
            cond = self.parse_expr()
            self.expect("THEN")
            then_e = self.parse_expr()
            self.expect("ELSE")
            else_e = self.parse_expr()
            return If(cond, then_e, else_e)
        return self.parse_cmp()

    def parse_cmp(self):
        left = self.parse_add()
        kind = self.tokens[self.pos][0]
        if kind == "EQEQ" or kind == "LT":
            op = self.tokens[self.pos][1]
            self.pos += 1
            right = self.parse_add()
            return BinOp(op, left, right)
        return left

    def parse_add(self):
        left = self.parse_mul()
        while True:
            kind = self.tokens[self.pos][0]
            if kind == "PLUS" or kind == "MINUS":
                op = self.tokens[self.pos][1]
                self.pos += 1
                right = self.parse_mul()
                left = BinOp(op, left, right)
            else:
                break
        return left

    def parse_mul(self):
        left = self.parse_app()
        while True:
            kind = self.tokens[self.pos][0]
            if kind == "STAR" or kind == "FLOORDIV" or kind == "PERCENT":
                op = self.tokens[self.pos][1]
                self.pos += 1
                right = self.parse_app()
                left = BinOp(op, left, right)
            else:
                break
        return left

    def parse_app(self):
        expr = self.parse_atom()
        while self.tokens[self.pos][0] in ATOM_START:
            arg = self.parse_atom()
            expr = App(expr, arg)
        return expr

    def parse_atom(self):
        tok = self.tokens[self.pos]
        kind = tok[0]
        if kind == "IDENT":
            self.pos += 1
            return Var(tok[1])
        if kind == "INT":
            self.pos += 1
            return IntLit(tok[1])
        if kind == "TRUE":
            self.pos += 1
            return BoolLit(True)
        if kind == "FALSE":
            self.pos += 1
            return BoolLit(False)
        if kind == "LPAREN":
            self.pos += 1
            e = self.parse_expr()
            if self.tokens[self.pos][0] == "COLON":
                self.pos += 1
                ty = self.parse_type()
                self.expect("RPAREN")
                return Anno(e, ty)
            self.expect("RPAREN")
            return e
        raise MCParseError(f"unexpected token {kind}")

    def parse_type(self):
        left = self.parse_tatom()
        if self.tokens[self.pos][0] == "ARROW":
            self.pos += 1
            right = self.parse_type()
            return TFun(left, right)
        return left

    def parse_tatom(self):
        kind = self.tokens[self.pos][0]
        if kind == "INT_TYPE":
            self.pos += 1
            return T_INT
        if kind == "BOOL_TYPE":
            self.pos += 1
            return T_BOOL
        if kind == "LPAREN":
            self.pos += 1
            t = self.parse_type()
            self.expect("RPAREN")
            return t
        raise MCParseError(f"expected type, got {kind}")


# ============================================================================
# 4. Typechecker
# ============================================================================

_MISSING = object()
ARITH_OPS = {"+", "-", "*", "//", "%"}


def deref(t):
    if isinstance(t, TVar) and t.instance is not None:
        r = t
        while isinstance(r, TVar) and r.instance is not None:
            r = r.instance
        while isinstance(t, TVar) and t.instance is not None:
            nxt = t.instance
            t.instance = r
            t = nxt
        return r
    return t


def occurs(v: TVar, t) -> bool:
    stack = [t]
    while stack:
        cur = deref(stack.pop())
        if cur is v:
            return True
        if isinstance(cur, TFun):
            stack.append(cur.arg)
            stack.append(cur.ret)
    return False


def unify(t1, t2):
    stack = [(t1, t2)]
    while stack:
        a, b = stack.pop()
        a = deref(a)
        b = deref(b)
        if a is b:
            continue
        if isinstance(a, TVar):
            if occurs(a, b):
                raise MCTypeError("infinite type")
            a.instance = b
        elif isinstance(b, TVar):
            if occurs(b, a):
                raise MCTypeError("infinite type")
            b.instance = a
        elif isinstance(a, TFun) and isinstance(b, TFun):
            stack.append((a.ret, b.ret))
            stack.append((a.arg, b.arg))
        else:
            raise MCTypeError("type mismatch")


def typecheck(expr):
    env = {}

    def infer(e):
        t = type(e)
        if t is IntLit:
            return T_INT
        if t is BoolLit:
            return T_BOOL
        if t is Var:
            res = env.get(e.name)
            if res is None:
                raise MCTypeError(f"unbound variable {e.name}")
            return res
        if t is Lam:
            param_ty = TVar()
            old = env.get(e.param, _MISSING)
            env[e.param] = param_ty
            try:
                ret_ty = infer(e.body)
            finally:
                if old is _MISSING:
                    del env[e.param]
                else:
                    env[e.param] = old
            return TFun(param_ty, ret_ty)
        if t is App:
            fn_ty = deref(infer(e.fn))
            arg_ty = infer(e.arg)
            if isinstance(fn_ty, TFun):
                unify(fn_ty.arg, arg_ty)
                return fn_ty.ret
            ret_ty = TVar()
            unify(fn_ty, TFun(arg_ty, ret_ty))
            return ret_ty
        if t is BinOp:
            lt = infer(e.left)
            unify(lt, T_INT)
            rt = infer(e.right)
            unify(rt, T_INT)
            return T_INT if e.op in ARITH_OPS else T_BOOL
        if t is If:
            ct = infer(e.cond)
            unify(ct, T_BOOL)
            tt = infer(e.then_e)
            et = infer(e.else_e)
            unify(tt, et)
            return tt
        if t is Anno:
            et = infer(e.expr)
            unify(et, e.ty)
            return e.ty
        if t is Let:
            vt = infer(e.val_e)
            if e.ty is not None:
                unify(vt, e.ty)
                bind_ty = e.ty
            else:
                bind_ty = vt
            old = env.get(e.name, _MISSING)
            env[e.name] = bind_ty
            try:
                return infer(e.body_e)
            finally:
                if old is _MISSING:
                    del env[e.name]
                else:
                    env[e.name] = old
        if t is LetRec:
            old = env.get(e.name, _MISSING)
            env[e.name] = e.ty
            try:
                vt = infer(e.lam_e)
                unify(vt, e.ty)
                return infer(e.body_e)
            finally:
                if old is _MISSING:
                    del env[e.name]
                else:
                    env[e.name] = old
        raise AssertionError(f"unknown AST node {e}")

    return infer(expr)


# ============================================================================
# 5. Bytecode Compiler & Stack VM
# ============================================================================

OP_CONST = 0
OP_LOAD_LOCAL = 1
OP_STORE_LOCAL = 2
OP_LOAD_FREE = 3
OP_MAKE_CLOSURE = 4
OP_MAKE_REC = 5
OP_ADD = 6
OP_SUB = 7
OP_MUL = 8
OP_DIV = 9
OP_MOD = 10
OP_EQ = 11
OP_LT = 12
OP_JUMP = 13
OP_JUMP_IF_FALSE = 14
OP_CALL = 15
OP_TAIL_CALL = 16
OP_RETURN = 17

BINOP_CODE = {
    "+": OP_ADD,
    "-": OP_SUB,
    "*": OP_MUL,
    "//": OP_DIV,
    "%": OP_MOD,
    "==": OP_EQ,
    "<": OP_LT,
}


class Code:
    __slots__ = ("ops", "nlocals")

    def __init__(self, ops: tuple, nlocals: int):
        self.ops = ops
        self.nlocals = nlocals


class Closure:
    __slots__ = ("code", "free")

    def __init__(self, code: Code, free):
        self.code = code
        self.free = free


class FuncBuilder:
    __slots__ = ("parent", "scope", "nlocals", "captures", "capture_map", "ops")

    def __init__(self, parent=None, param_name=None):
        self.parent = parent
        self.scope = {}
        self.nlocals = 0
        self.captures = []
        self.capture_map = {}
        self.ops = []
        if param_name is not None:
            self.scope[param_name] = 0
            self.nlocals = 1

    def alloc_local(self) -> int:
        idx = self.nlocals
        self.nlocals += 1
        return idx

    def resolve(self, name: str):
        slot = self.scope.get(name)
        if slot is not None:
            return (True, slot)
        parent_loc = self.parent.resolve(name)
        fidx = self.capture_map.get(parent_loc)
        if fidx is None:
            fidx = len(self.captures)
            self.captures.append(parent_loc)
            self.capture_map[parent_loc] = fidx
        return (False, fidx)


def compile_program(expr) -> Code:
    def emit_expr(fb: FuncBuilder, e, tail: bool):
        while type(e) is Anno:
            e = e.expr
        t = type(e)
        if t is IntLit or t is BoolLit:
            fb.ops.append((OP_CONST, e.val))
            if tail:
                fb.ops.append((OP_RETURN, None))
            return
        if t is Var:
            is_local, idx = fb.resolve(e.name)
            fb.ops.append((OP_LOAD_LOCAL if is_local else OP_LOAD_FREE, idx))
            if tail:
                fb.ops.append((OP_RETURN, None))
            return
        if t is Lam:
            child = FuncBuilder(parent=fb, param_name=e.param)
            emit_expr(child, e.body, True)
            child_code = Code(tuple(child.ops), child.nlocals)
            fb.ops.append((OP_MAKE_CLOSURE, (child_code, tuple(child.captures))))
            if tail:
                fb.ops.append((OP_RETURN, None))
            return
        if t is App:
            emit_expr(fb, e.fn, False)
            emit_expr(fb, e.arg, False)
            if tail:
                fb.ops.append((OP_TAIL_CALL, None))
            else:
                fb.ops.append((OP_CALL, None))
            return
        if t is BinOp:
            emit_expr(fb, e.left, False)
            emit_expr(fb, e.right, False)
            fb.ops.append((BINOP_CODE[e.op], None))
            if tail:
                fb.ops.append((OP_RETURN, None))
            return
        if t is If:
            emit_expr(fb, e.cond, False)
            jmp_false_idx = len(fb.ops)
            fb.ops.append(None)  # placeholder
            emit_expr(fb, e.then_e, tail)
            if tail:
                else_pc = len(fb.ops)
                fb.ops[jmp_false_idx] = (OP_JUMP_IF_FALSE, else_pc)
                emit_expr(fb, e.else_e, True)
            else:
                jmp_end_idx = len(fb.ops)
                fb.ops.append(None)  # placeholder
                else_pc = len(fb.ops)
                fb.ops[jmp_false_idx] = (OP_JUMP_IF_FALSE, else_pc)
                emit_expr(fb, e.else_e, False)
                end_pc = len(fb.ops)
                fb.ops[jmp_end_idx] = (OP_JUMP, end_pc)
            return
        if t is Let:
            emit_expr(fb, e.val_e, False)
            slot = fb.alloc_local()
            fb.ops.append((OP_STORE_LOCAL, slot))
            old = fb.scope.get(e.name, _MISSING)
            fb.scope[e.name] = slot
            try:
                emit_expr(fb, e.body_e, tail)
            finally:
                if old is _MISSING:
                    del fb.scope[e.name]
                else:
                    fb.scope[e.name] = old
            return
        if t is LetRec:
            slot = fb.alloc_local()
            old = fb.scope.get(e.name, _MISSING)
            fb.scope[e.name] = slot
            try:
                lam = e.lam_e
                child = FuncBuilder(parent=fb, param_name=lam.param)
                emit_expr(child, lam.body, True)
                child_code = Code(tuple(child.ops), child.nlocals)
                self_fidx = child.capture_map.get((True, slot), -1)
                fb.ops.append((OP_MAKE_REC, (child_code, tuple(child.captures), self_fidx, slot)))
                emit_expr(fb, e.body_e, tail)
            finally:
                if old is _MISSING:
                    del fb.scope[e.name]
                else:
                    fb.scope[e.name] = old
            return
        raise AssertionError(f"unexpected AST node {e}")

    root = FuncBuilder()
    emit_expr(root, expr, True)
    return Code(tuple(root.ops), root.nlocals)


def run_vm(top_code: Code):
    ops = top_code.ops
    pc = 0
    loc = [None] * top_code.nlocals
    free = ()
    stack = []
    push = stack.append
    pop = stack.pop
    call_stack = []
    cs_push = call_stack.append
    cs_pop = call_stack.pop

    while True:
        op, arg = ops[pc]
        pc += 1
        if op == OP_LOAD_LOCAL:
            push(loc[arg])
        elif op == OP_CONST:
            push(arg)
        elif op == OP_STORE_LOCAL:
            loc[arg] = pop()
        elif op == OP_LOAD_FREE:
            push(free[arg])
        elif op == OP_ADD:
            b = pop()
            push(pop() + b)
        elif op == OP_SUB:
            b = pop()
            push(pop() - b)
        elif op == OP_MUL:
            b = pop()
            push(pop() * b)
        elif op == OP_DIV:
            b = pop()
            a = pop()
            if b == 0:
                raise MCRuntimeError("division by zero")
            push(a // b)
        elif op == OP_MOD:
            b = pop()
            a = pop()
            if b == 0:
                raise MCRuntimeError("modulo by zero")
            push(a % b)
        elif op == OP_EQ:
            b = pop()
            push(pop() == b)
        elif op == OP_LT:
            b = pop()
            push(pop() < b)
        elif op == OP_JUMP_IF_FALSE:
            if not pop():
                pc = arg
        elif op == OP_JUMP:
            pc = arg
        elif op == OP_CALL:
            aval = pop()
            fn = pop()
            cs_push((ops, pc, loc, free))
            c = fn.code
            ops = c.ops
            pc = 0
            free = fn.free
            nloc = c.nlocals
            loc = [None] * nloc
            loc[0] = aval
        elif op == OP_TAIL_CALL:
            aval = pop()
            fn = pop()
            c = fn.code
            ops = c.ops
            pc = 0
            free = fn.free
            nloc = c.nlocals
            if len(loc) == nloc:
                loc[0] = aval
            else:
                loc = [None] * nloc
                loc[0] = aval
        elif op == OP_RETURN:
            if not call_stack:
                return pop()
            ops, pc, loc, free = cs_pop()
        elif op == OP_MAKE_CLOSURE:
            c_code, caps = arg
            if caps:
                c_free = tuple(loc[i] if is_l else free[i] for is_l, i in caps)
            else:
                c_free = ()
            push(Closure(c_code, c_free))
        elif op == OP_MAKE_REC:
            c_code, caps, self_fidx, slot = arg
            if caps:
                c_free = [loc[i] if is_l else free[i] for is_l, i in caps]
            else:
                c_free = []
            clos = Closure(c_code, c_free)
            if self_fidx >= 0:
                c_free[self_fidx] = clos
            loc[slot] = clos


def format_value(val) -> str:
    if isinstance(val, bool):
        return "True" if val else "False"
    if isinstance(val, int):
        return str(val)
    if isinstance(val, Closure):
        return "<function>"
    raise AssertionError(f"unexpected value {val!r}")


def main():
    if len(sys.argv) != 3 or sys.argv[1] != "run":
        sys.stderr.write("Usage: minicore run FILE\n")
        sys.exit(1)

    filepath = sys.argv[2]
    try:
        with open(filepath, "rb") as f:
            raw = f.read()
    except OSError as e:
        sys.stderr.write(f"Error reading file: {e}\n")
        sys.exit(1)

    try:
        if not raw.isascii():
            raise MCParseError("non-ASCII character in source")
        src = raw.decode("ascii")
        tokens = tokenize(src)
        ast = Parser(tokens).parse_program()
        typecheck(ast)
        code = compile_program(ast)
        val = run_vm(code)
    except MCParseError:
        sys.stdout.write("ParseError\n")
        sys.exit(1)
    except MCTypeError:
        sys.stdout.write("TypeError\n")
        sys.exit(1)
    except MCRuntimeError:
        sys.stdout.write("RuntimeError\n")
        sys.exit(1)

    sys.stdout.write(format_value(val) + "\n")
    sys.exit(0)


if __name__ == "__main__":
    main()
